-- Seed the About page with the content previously hardcoded in the frontend about.astro route
INSERT OR IGNORE INTO `site_content` (`id`, `content`) VALUES ('about', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The documentaries, interviews, and images bring the voices alive from those who experienced World War II in an up close and personal way. These are their stories, when freedom stood in the balance and a generation of the free made a difference in the world."}]},{"type":"paragraph","content":[{"type":"text","text":"In 2002 Military Historian and Producer/Director Vernon L. Williams established the East Anglia Air War Project with a mission to document the American air war against the German empire in the ETO. For twenty-three years, Dr. Williams has traveled across the United States interviewing ground and air crews who served in wartime England during the Second World War."}]},{"type":"paragraph","content":[{"type":"text","text":"Meanwhile, Williams made countless trips to England and searched out British family members who lived in the villages around the airfields across East Anglia. The net result of more than two decades of research, oral history interviews, and an extensive document archive, Williams has produced over a dozen full length broadcast quality documentaries on the air war, with more on the way, recorded hundreds of comprehensive oral history interviews, and collected more than fifty thousand World War Two photographs. Now the East Anglia Air War Collection is available on a new streaming service through the Air War Trail."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"About the Historian"}]},{"type":"paragraph","content":[{"type":"text","text":"Dr. Vernon L. Williams is a military and naval historian. He received his doctorate from Texas A&M University in 1985. He is currently serving as President of the Old Primero Historical Foundation and Director of the East Anglia Air War Project. Before 2018 he spent thirty years as professor of history in the Department of History at Abilene Christian University. Since 2001 Dr. Williams has been working to document the wartime experiences of American and British citizens alike. Planned outcomes from this project include several books over the next few years and a continuing series of documentary films."}]},{"type":"paragraph","content":[{"type":"text","text":"Recently, Dr. Williams has completed two books:"}]},{"type":"paragraph","content":[{"type":"text","text":"Flight Surgeon: A War Diary, 1941-1945, Edited by Vernon L. Williams, TCU University Press, 2021"}]},{"type":"paragraph","content":[{"type":"text","text":"Empire Marine: Major General Littleton W.T. Waller and the Growth of American Imperialism, 1856-1926, TCU University Press, 2024"}]},{"type":"paragraph","content":[{"type":"text","text":"Currently, Dr. Williams is writing a volume about the sense of community that developed between the Americans and British families living in villages around the American bases in wartime England. The working title for the book is: Little America: The Anglo/American Cultural Exchange in World War II England, 1942-1945, in progress with an expected completion and submission date at the end of 2026. Little America will be organized into ten chapters:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Preface"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 1.  Setting the Stage"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 2.  Little America, A Sense of Place"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 3.  The Red Cross and the Aero Clubs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 4.  Race: The Shifting Landscape"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 5.  Big Bands and the Jitterbug"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 6.  The Moral Dilemma"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 7.  Glamour and Hollywood"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 8.  War Brides"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 9.  Bonds that are Never Broken"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chapter 10. Epilogue"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Six new documentaries have been released by Dr. Williams for Old Segundo Productions in recent years. Three of these films appear in the Air War Series and three in the History of the American West Series. During the last twenty years, Dr. Williams has produced over twenty-one documentary films on military and American history subjects."}]},{"type":"paragraph","content":[{"type":"text","text":"Cokedale, Colorado, 1907-1947: A Model Company Town and the Promise of Hope and Community, released 2024"}]},{"type":"paragraph","content":[{"type":"text","text":"Wethersfield at War: From World War II to the Cold War, An Essex Story of Service, Determination, and the Anglo-American Spirit, released 2023"}]},{"type":"paragraph","content":[{"type":"text","text":"Primero, Colorado, 1901-1928: John D. Rockefeller, Jr., Company Towns, and the Quest for a Better World, released 2018"}]},{"type":"paragraph","content":[{"type":"text","text":"Rendezvous Over Berlin, A Texas Cowboy Finds His Destiny Over the Skies of Nazi Germany, 1942-1943, released 2020"}]},{"type":"paragraph","content":[{"type":"text","text":"Willard, Colorado: The Burlington Railroad, Community, and Life on the Twentieth Century’s Colorado High Plains, released in 2020"}]},{"type":"paragraph","content":[{"type":"text","text":"From Ozark to Fortress Europe: Flight Surgeon Thurman Shuller, War, Medicine, and a Life of Service, released 2021"}]},{"type":"paragraph","content":[{"type":"text","text":"Williams’ first documentary film, Deopham Green, appeared in 2004 and since that time, he has produced and directed twenty documentaries on various subjects. You can visit oldsegundo.com to find information on the films that are currently available and learn about others that are now in the production and pre-production stages."}]},{"type":"paragraph","content":[{"type":"text","text":"Academic Background"},{"type":"hardBreak"},{"type":"text","text":"Ph.D., 1985"},{"type":"hardBreak"},{"type":"text","text":"Texas A&M University, College Station, Texas"},{"type":"hardBreak"},{"type":"text","text":"Major: American Military and Naval History"},{"type":"hardBreak"},{"type":"text","text":"Minors: American West and Nautical Archaeology"}]}]}');